// DevControl push service worker (scope /push/). It is separate from the PWA
// service worker (/sw.js, generated by next-pwa) on purpose: nothing here
// depends on the next-pwa build, so a failure in one never blocks the other.
// A worker with a narrow scope still receives push events and can show
// notifications and open any page of this origin.

self.addEventListener("install", () => { self.skipWaiting(); });
self.addEventListener("activate", (event) => { event.waitUntil(self.clients.claim()); });

self.addEventListener("push", (event) => {
  let data = {};
  try {
    data = event.data ? event.data.json() : {};
  } catch (_) {
    data = { body: event.data ? event.data.text() : "" };
  }
  const options = {
    body: data.body || "",
    icon: "/api/branding/icon?size=192",
    data: { url: typeof data.url === "string" && data.url.startsWith("/") ? data.url : "/" },
  };
  if (data.tag) {
    options.tag = data.tag;
    options.renotify = true;
  }
  event.waitUntil(self.registration.showNotification(data.title || "DevControl", options));
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const path = (event.notification.data && event.notification.data.url) || "/";
  const target = new URL(path, self.location.origin).href;
  event.waitUntil((async () => {
    // includeUncontrolled returns every open DevControl tab of this origin,
    // not only pages inside this worker's /push/ scope.
    const windows = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
    for (const client of windows) {
      if (new URL(client.url).origin !== self.location.origin) continue;
      await client.focus();
      if ("navigate" in client) {
        try { await client.navigate(target); } catch (_) { /* not controlled by this worker: focusing is enough */ }
      }
      return;
    }
    await self.clients.openWindow(target);
  })());
});
